-- Stores the platform's Flower SuperLink CA (certificate and private key), generated by the
-- aggregator attempt of the platform's first Flower run, so every later run reuses the same CA:
-- clinics get the certificate, the platform's aggregator gets both and signs its leaf with them.
-- Empty until the platform's first Flower run ever.
create table flower_platform_certificate
(
    id             bigint generated by default as identity,
    created_at     timestamp(6) not null,
    updated_at     timestamp(6) not null,
    version        bigint default 0 not null,
    ca_certificate TEXT not null,
    ca_private_key TEXT not null,
    primary key (id)
);
